  VALUES ('linux', 'tr', 'mid', 'Bir süreci sonlandırmak için kullanılan `kill -15` (SIGTERM) ve `kill -9` (SIGKILL) arasındaki fark nedir?', 'SIGTERM (15) nazik bir istektir; süreç dosyaları kapatabilir, durumu kaydedebilir. SIGKILL (9) ise sürece söz hakkı tanımaz ve doğrudan yok eder.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'SIGTERM süreci anında öldürür; SIGKILL ise sürecin kendi kendine kapanmasını bekler.' FROM q
UNION ALL
  SELECT id, 1, 'SIGTERM sürece düzgünce kapanması için sinyal gönderir (clean-up yapabilir); SIGKILL süreci işletim sistemi seviyesinde zorla ve anında sonlandırır.' FROM q
UNION ALL
  SELECT id, 2, 'SIGTERM sadece arka plan süreçleri içindir, SIGKILL sadece ön plan süreçleri içindir.' FROM q
UNION ALL
  SELECT id, 3, 'İki sinyal arasında fark yoktur, sadece farklı Linux dağıtımlarında farklı isimler alırlar.' FROM q;

