WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('git', 'tr', 'mid', '`git merge` ve `git rebase` arasındaki en temel fark nedir?', '`merge` geçmişi olduğu gibi korur (branched history). `rebase` ise commitleri tek bir çizgi üzerinde birleştirerek daha temiz bir görünüm sağlar ancak ortak dallarda kullanımı risklidir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, '`merge` sadece bir kez yapılır, `rebase` sınırsız yapılabilir.' FROM q
UNION ALL
  SELECT id, 1, '`merge` yeni bir ''merge commit'' oluşturarak dalları birleştirir; `rebase` ise commit geçmişini yeniden yazarak değişiklikleri hedef dalın üzerine taşır ve doğrusal bir geçmiş sunar.' FROM q
UNION ALL
  SELECT id, 2, '`rebase` verileri siler, `merge` verileri korur.' FROM q
UNION ALL
  SELECT id, 3, '`merge` sadece yerel dallarda, `rebase` ise sadece uzak dallarda çalışır.' FROM q;

